 r.roots=count=>{const result=[];while(result.length<count){const x=r.i(-6,6);if(!result.includes(x))result.push(x);}return result;};
 const content=item.make(r),q={...content,id:`m1e3-${seed>>>0}-${index}-${topic.id}-${type}-${item.id}`,generatorVersion:3,program:'general-math-1',educationMode:'university',subject,index,template:item.id,scope:{...selection},topicId:topic.id,subtopicId:type,diagram:'',responseType:item.type,supportsChoices:false,choices:[],correct:null,answerUnit:'',difficultyProfile:{base:item.level,steps:content.workSteps,type:item.type}};
 q.difficulty=QuestionDifficulty.estimate(q);return q;
